-- The 84M-row firehose: every itemized donation individuals gave to federal committees. The rawest follow-the-money.
-- Auto-generated by scripts/gen_evidence_pages.py: 84,172,112 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("TRANSACTION_DT") as year, count(*) as records
from THE_LIBRARY.CAMPAIGN_FINANCE.INDIVIDUAL_DONATIONS
where "TRANSACTION_DT" is not null
group by 1
order by 1
